WITH w AS (SELECT r.id, r.type, r.home_id, r.created_at_ms, r.name, r.body, (SELECT l.target_id FROM links l WHERE l.source_id = r.id AND l.relationship = 'part_of' ORDER BY l.target_id LIMIT 1) AS bearer_id FROM records r WHERE r.type IN ('Message', 'Annotation') AND r.kind IN ('text', 'comment') AND r.deleted_at IS NULL AND (r.created_at_ms < ?1 OR (r.created_at_ms = ?1 AND r.id < ?2)) ORDER BY r.created_at_ms DESC, r.id DESC LIMIT 200) SELECT s.stage AS private_stage, s.archived AS private_archived, s.unread AS private_unread, s.is_own AS private_own, s.mentioned AS private_mentioned, EXISTS(SELECT 1 FROM my_mentions mm WHERE mm.source_id=w.id) AS private_reference, w.id, origin.id AS origin_id, origin.name AS origin_name, a.person_id AS actor_person_id, a.display_name AS actor_name, CASE w.type WHEN 'Message' THEN 'message' ELSE 'comment' END AS kind, w.created_at_ms, w.name AS title, substr(w.body, 1, 1200) AS body, length(w.body) AS body_len, (SELECT e.actor FROM content_events e WHERE e.record_id = w.id AND e.type IN ('record.created','kernel.message_created.v1') ORDER BY e.local_seq LIMIT 1) AS actor, (SELECT e.run_key FROM content_events e WHERE e.record_id = w.id AND e.type IN ('record.created','kernel.message_created.v1') ORDER BY e.local_seq LIMIT 1) AS run_key, (SELECT l.target_id FROM links l WHERE l.source_id = w.id AND l.relationship = 'addressed_to' ORDER BY l.target_id LIMIT 1) AS to_id, (SELECT p.name FROM links l JOIN records p ON p.id = l.target_id WHERE l.source_id = w.id AND l.relationship = 'addressed_to' ORDER BY l.target_id LIMIT 1) AS to_name, (SELECT l.target_id FROM links l WHERE l.source_id = w.id AND l.relationship = 'reply_to' ORDER BY l.target_id LIMIT 1) AS reply_to, w.bearer_id, (SELECT b.type FROM records b WHERE b.id = w.bearer_id) AS bearer_type, (SELECT b.name FROM records b WHERE b.id = w.bearer_id) AS bearer_name, (SELECT v.value FROM facet_values v WHERE v.record_id = w.id AND v.key = 'expectation') AS expectation, (SELECT group_concat(reaction_id, ':') FROM (SELECT reaction_id FROM message_reactions WHERE message_id=w.id ORDER BY reaction_id)) AS reaction_revision FROM w LEFT JOIN my_message_state s ON s.message_id=w.id LEFT JOIN records origin ON origin.id = w.home_id LEFT JOIN actors a ON a.actor = (SELECT e.actor FROM content_events e WHERE e.record_id = w.id AND e.type IN ('record.created','kernel.message_created.v1') ORDER BY e.local_seq LIMIT 1) ORDER BY w.created_at_ms DESC, w.id DESC LIMIT 200
